PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT DEFAULT 'analyst');
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp DATETIME NOT NULL, source_ip TEXT, hostname TEXT, app_name TEXT, facility TEXT, severity TEXT, message TEXT NOT NULL, raw_json TEXT);
CREATE INDEX IF NOT EXISTS idx_events_timestamp ON events(timestamp);
CREATE TABLE IF NOT EXISTS sigma_rules (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, rule_yaml TEXT NOT NULL, enabled BOOLEAN DEFAULT 0);
CREATE TABLE IF NOT EXISTS yara_rules (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, rule_text TEXT NOT NULL, enabled BOOLEAN DEFAULT 1);
CREATE TABLE IF NOT EXISTS alerts (id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, rule_id INTEGER, event_id INTEGER, severity TEXT, acknowledged BOOLEAN DEFAULT 0, FOREIGN KEY(rule_id) REFERENCES sigma_rules(id), FOREIGN KEY(event_id) REFERENCES events(id));
CREATE TABLE IF NOT EXISTS drop_rules (id INTEGER PRIMARY KEY AUTOINCREMENT, field TEXT NOT NULL, operator TEXT NOT NULL, value TEXT NOT NULL, description TEXT, enabled BOOLEAN DEFAULT 1);
CREATE TABLE IF NOT EXISTS stix_indicators (stix_id TEXT PRIMARY KEY, type TEXT NOT NULL, name TEXT, description TEXT, pattern TEXT NOT NULL, valid_from DATETIME, revoked BOOLEAN DEFAULT 0, inserted_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_stix_pattern ON stix_indicators(pattern);
